const { Sequelize, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function stripFields(instance, fields) {
  const data = { ...instance.get() };

  for (const field of fields) {
    delete data[field];
  }

  return data;
}

class SerializableModel extends Model {
  toJSON() {
    return stripFields(this, this.constructor.hiddenFields ?? []);
  }
}

module.exports = { sequelize, SerializableModel };

export async function requestJson(url, options = {}, errorPrefix = "Request failed") {
  const res = await fetch(url, options);

  if (!res.ok) {
    let detail = "";

    try {
      const body = await res.json();
      if (body?.error) {
        detail = ` (${body.error})`;
      }
    } catch {
      // Ignore non-JSON error bodies and fall back to the status code.
    }

    throw new Error(`${errorPrefix}: ${res.status}${detail}`);
  }

  return res.json();
}

