import { useEffect, useState } from "react";
import { getComments } from "./api";

export default function useComments(slug) {
  const [comments, setComments] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    setComments([]);
    setError(null);

    getComments(slug, { signal: controller.signal })
      .then((nextComments) => {
        if (!controller.signal.aborted) {
          setComments(nextComments);
        }
      })
      .catch((err) => {
        if (err?.name === "AbortError") return;
        setError(err?.message ?? "Failed to load comments");
      });

    return () => controller.abort();
  }, [slug]);

  return { comments, error };
}

"use strict";

const { Sequelize, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

function stripFields(instance, fields) {
  const data = { ...instance.get() };

  for (const field of fields) {
    delete data[field];
  }

  return data;
}

class SerializableModel extends Model {
  toJSON() {
    return stripFields(this, this.constructor.hiddenFields ?? []);
  }
}

function defineSerializableModel(ModelClass, attributes, options = {}) {
  const { modelName, hiddenFields = [] } = options;

  ModelClass.hiddenFields = hiddenFields;
  ModelClass.init(attributes, { sequelize, modelName });

  return ModelClass;
}

module.exports = { sequelize, SerializableModel, defineSerializableModel };

